Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<cstdio>
#include<cstring>
#include<algorithm>
#define rep(i,a,b) for(i=a;i<=b;i++)
using namespace std;
const int N=300010;
//const int N=20;
int n,K,mod;
int dp[N][20];
int cnt[N],mx[N];
int cj[N],inv[N];

int power(int x,int y){
	int ret=1;
	for(;y;y>>=1,x=1ll*x*x%mod){
		if(y&1)	ret=1ll*ret*x%mod;
	}
	return ret;
}

int C(int i,int j){
	return 1ll*cj[i]*inv[j]%mod*inv[i-j]%mod;
}

int main(){
//	freopen("a.in","r",stdin);
//	freopen("a.out","w",stdout);
	scanf("%d%d%d",&n,&K,&mod);
	int i,j,k;int ans=0;int down,up,tmp,now,cur1,cur2;
	if(n&1){printf("%d\n",power(K,n));return 0;}
	cj[0]=1;rep(i,1,n)	cj[i]=1ll*cj[i-1]*i%mod;
	inv[n]=power(cj[n],mod-2);inv[0]=1;
	for(i=n-1;i;i--)	inv[i]=1ll*inv[i+1]*(i+1)%mod;
	rep(i,1,n)
		rep(j,0,18)
			if(1<<j&i)	cnt[i]++;
	rep(i,1,n)
		for(j=18;j>=0;j--)
			if(1<<j&i){mx[i]=1<<j;break;}
	dp[0][0]=1;
	rep(i,1,n){
		if((n&i)!=i)	continue;
		now=i^mx[i];
		for(k=now;k>=0;k=(k-1)&now){			
			cur1=k+mx[i];cur2=i^cur1;
			up=min(K-1,cnt[cur2]);
			tmp=C(i,cur1);	
			rep(j,0,up){
				dp[i][j+1]=(dp[i][j+1]+1ll*dp[cur2][j]*tmp)%mod;						
			}
			if(k==0)	break;
		}
	}
	rep(j,1,min(cnt[n],K))	ans=(ans+1ll*dp[n][j]*C(K,j)%mod*cj[j])%mod;
	ans=(power(K,n)-ans+mod)%mod;
	printf("%d\n",ans);
	return 0;
}
































